function validate([s, spaces]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 300000) return 's needs 1 to 3 * 10^5 characters.';
  if (!/^[A-Za-z]+$/.test(s)) return 's contains only English letters.';
  if (!Array.isArray(spaces) || spaces.length < 1 || spaces.length > 300000) return 'spaces needs 1 to 3 * 10^5 indices.';
  for (let i = 0; i < spaces.length; i++) {
    if (!Number.isInteger(spaces[i]) || spaces[i] < 0 || spaces[i] >= s.length) return 'Each index in spaces is from 0 to s.length - 1.';
    if (i > 0 && spaces[i] <= spaces[i - 1]) return 'spaces must be strictly increasing.';
  }
  return null;
}

