function addSpaces(s, spaces) {
  const parts = [];
  let next = 0;
  for (let i = 0; i < s.length; i++) {
    if (next < spaces.length && spaces[next] === i) {
      parts.push(' ');
      next++;
    }
    parts.push(s[i]);
  }
  return parts.join('');
}

