function addSpaces(s, spaces) {
  // Insert from the last index backwards so earlier indices still point at the original characters.
  let result = s;
  for (let k = spaces.length - 1; k >= 0; k--) {
    result = result.slice(0, spaces[k]) + ' ' + result.slice(spaces[k]);
  }
  return result;
}

