function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const length = size === 'large' ? 6000 + Math.floor(rand() * 2001) : 1 + Math.floor(rand() * 12);
  // Some strings use a tiny alphabet, which makes repeated letters.
  const alphabet = rand() < 0.3 ? 2 : letters.length;
  let s = '';
  for (let i = 0; i < length; i++) s += letters[Math.floor(rand() * alphabet)];
  const limit = size === 'large' ? 2000 : length;
  const chance = rand() < 0.2 ? 0.9 : rand() * 0.5;
  let spaces = [];
  for (let i = 0; i < length && spaces.length < limit; i++) {
    if (rand() < chance) spaces.push(i);
  }
  if (spaces.length === 0) spaces = [Math.floor(rand() * length)];
  return [s, spaces];
}
